<script>
(() => {
  const display = document.getElementById('display');
  let entry = '', stored = null, operator = null, resetNext = false, memory = 0;
  const show = value => { display.textContent = value; };
  const current = () => Number(entry || display.textContent || 0);
  function digit(v){
    if(resetNext){ entry=''; resetNext=false; }
    if(v==='.' && (entry || display.textContent).includes('.')) return;
    entry = (entry || '') + v;
    show(entry);
  }
  function calculate(a,b,op){
    if(op==='+') return a+b;
    if(op==='-') return a-b;
    if(op==='*') return a*b;
    if(op==='/') return b===0 ? NaN : a/b;
    if(op==='%') return a%b;
    return b;
  }
  function choose(op){
    const n=current();
    if(operator && !resetNext){
      const result=calculate(stored,n,operator);
      stored=result; show(String(result));
    }else stored=n;
    operator=op; resetNext=true; entry='';
  }
  function equals(){
    if(operator===null) return;
    const result=calculate(stored,current(),operator);
    show(Number.isFinite(result) ? String(Number(result.toPrecision(12))) : 'Error');
    entry=display.textContent; stored=null; operator=null; resetNext=true;
  }
  document.querySelectorAll('.key').forEach(key=>{
    key.addEventListener('click',()=>{
      const value=key.dataset.value, action=key.dataset.action;
      if(value!==undefined){ if('0123456789.'.includes(value)) digit(value); else choose(value); return; }
      switch(action){
        case 'clear': entry='';stored=null;operator=null;resetNext=false;show('');break;
        case 'equals':equals();break;
        case 'sqrt':show(String(Math.sqrt(current())));entry=display.textContent;resetNext=true;break;
        case 'sign':show(String(-current()));entry=display.textContent;break;
        case 'back':entry=(entry||display.textContent).slice(0,-1);show(entry);break;
        case 'mc':memory=0;break;
        case 'mr':entry=String(memory);show(entry);break;
        case 'mplus':memory+=current();break;
        case 'mminus':memory-=current();break;
      }
    });
  });
  document.addEventListener('keydown',e=>{
    if(/^[0-9.]$/.test(e.key)){digit(e.key);e.preventDefault();}
    else if(['+','-','*','/','%'].includes(e.key)) choose(e.key);
    else if(e.key==='Enter'||e.key==='='){equals();e.preventDefault();}
    else if(e.key==='Escape'){entry='';stored=null;operator=null;show('');}
    else if(e.key==='Backspace'){entry=entry.slice(0,-1);show(entry);}
  });
  document.getElementById('fullscreen').addEventListener('click',()=>{
    if(document.documentElement.requestFullscreen) document.documentElement.requestFullscreen().catch(()=>{});
  });
})();
</script>
